import{_ as e,o,c as i,ag as t}from"./chunks/framework.CrXGS008.js";const j=JSON.parse('{"title":"Stacje","description":"","frontmatter":{},"headers":[],"relativePath":"pl/repair-station/stations.md","filePath":"pl/repair-station/stations.md"}'),n={name:"pl/repair-station/stations.md"};function r(s,a,c,p,l,d){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="stacje" tabindex="-1">Stacje <a class="header-anchor" href="#stacje" aria-label="Permalink to &quot;Stacje&quot;">​</a></h1><p>Stacja to strefa zatrzymania pojazdów z promieniem, procentem ceny i, jeśli chcesz, propem, na przykład skrzynią z narzędziami postawioną obok. Trzy stacje są gotowe: <strong>Hayes Autos</strong>, <strong>Sandy Shores</strong> i <strong>Paleto Bay</strong>.</p><h2 id="jak-przebiega-naprawa" tabindex="-1">Jak przebiega naprawa <a class="header-anchor" href="#jak-przebiega-naprawa" aria-label="Permalink to &quot;Jak przebiega naprawa&quot;">​</a></h2><ol><li>Kierowca zatrzymuje się w promieniu stacji. Podpowiedź pokazuje najniższą cenę.</li><li><strong>E</strong> otwiera menu napraw z uszkodzeniami pojazdu i usługami wraz z cenami (zniżki dla zawodów i procent stacji wliczone).</li><li>Cena zostaje pobrana, silnik się wyłącza, a maska się otwiera. Pasek postępu trwa tyle, ile usługa, z dźwiękiem i iskrami. Naciśnij <strong>X</strong>, aby anulować.</li><li>Po zakończeniu naprawiane części są sprawne i pojazd może odjechać.</li></ol><p>Stacja odrzuca naprawę, gdy:</p><ul><li>stacja jest zamknięta lub <code>Enabled</code> jest wyłączone;</li><li>gracz nie prowadzi pojazdu albo pojazd nie jest w strefie stacji;</li><li>pojazd jest w ruchu;</li><li>stacja jest już zajęta (jeden pojazd naraz);</li><li>klasa pojazdu jest zablokowana (<code>BlockedClasses</code>);</li><li>usługa niczego nie naprawia w tym pojeździe, a <code>RequireDamage</code> jest włączone;</li><li>gracz musi poczekać na koniec odstępu (<code>CooldownSeconds</code>);</li><li>na służbie są mechanicy, patrz niżej;</li><li>gracz nie może zapłacić.</li></ul><p>Jeśli gracz wysiądzie z pojazdu, odjedzie lub anuluje, albo gdy stacja zostanie zamknięta lub usunięta w trakcie naprawy, naprawa się kończy, a graczowi zwracana jest pobrana kwota na obciążone konto.</p><h2 id="mechanicy-na-słuzbie" tabindex="-1">Mechanicy na służbie <a class="header-anchor" href="#mechanicy-na-słuzbie" aria-label="Permalink to &quot;Mechanicy na służbie&quot;">​</a></h2><p>Gracze prowadzący warsztat nie powinni tracić klientów na rzecz stacji. Wpisz ich zawody w <code>MechanicJobs</code> i ustaw <code>MaxMechanicsOnDuty</code>: dopóki na służbie jest tylu mechaników lub więcej, wszystkie stacje są zamknięte i odsyłają graczy do nich. Przy <code>0</code> stacje nigdy nie zamykają się z tego powodu.</p><h2 id="edytor-stacji" tabindex="-1">Edytor stacji <a class="header-anchor" href="#edytor-stacji" aria-label="Permalink to &quot;Edytor stacji&quot;">​</a></h2><p>Otwórz go przez <code>/nay:repair</code> albo przez <strong>Zarządzaj stacjami</strong> na stronie Repair Station w <code>/nay</code>. Wymaga scope <code>nay_repair.config</code>.</p><ol><li><strong>Nowa stacja tutaj</strong>: stań tam, gdzie pojazdy mają się zatrzymywać, w pojeździe lub pieszo. Stacja przyjmuje Twoją pozycję i kierunek.</li><li>Wybierz pozycję pojazdu (<strong>Postój pojazdu</strong>) lub propa (<strong>Prop</strong>) albo naciśnij Tab i przesuń ją: <ul><li>strzałki: do przodu, do tyłu, w lewo, w prawo, względem kamery;</li><li>Page Up / Page Down: wysokość;</li><li>Q / E: obrót;</li><li>Shift: drobne kroki.</li><li>G: chodzenie pieszo (<strong>Chodź</strong>), a ponowne G wraca do panelu.</li></ul></li><li><strong>Do mojej pozycji</strong> i <strong>Na ziemię</strong> ustawiają wybrany element.</li><li>Ustaw nazwę, promień, procent ceny, blip i prop. Proponowane propy: <code>prop_toolchest_05</code>, <code>prop_toolchest_01</code>, <code>prop_carcreeper</code>, <code>prop_compressor_03</code> lub dowolna nazwa modelu.</li><li><strong>Enter</strong> zapisuje, także podczas wpisywania w polu, <strong>Backspace</strong> lub <strong>Escape</strong> anuluje. Stacja działa od razu dla wszystkich graczy.</li></ol><p>Menedżer pozwala też przejść do stacji, otworzyć ją lub zamknąć i usunąć (naciśnij dwa razy, aby potwierdzić). Edytor wypełnia ustawienie <code>Stations</code>, opisane na stronie <a href="/pl/repair-station/settings#stations">Ustawienia</a>. Każda stacja dostaje identyfikator, który nigdy się nie zmienia.</p>',13)])])}const u=e(n,[["render",r]]);export{j as __pageData,u as default};
